#!/usr/bin/env node
// scripts/gen-prompts.mjs — compiles prompts/*.md + knowledge/domains/*.md into ONE
// ES module, prompts/prompts.generated.js, so the SAME text reaches the browser
// bundle (src/constants.js), the Node API routes, and Supabase Edge Functions.
// The .md files are the source of truth — versioned, diffable, reviewed in a PR.
// Runs in `npm run build` (before check-tokens/vite). `--check` fails if the
// committed generated file is stale.
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const OUT = path.join(ROOT, 'prompts/prompts.generated.js');
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').trim();
const js = (s) => JSON.stringify(s);

const domainsDir = path.join(ROOT, 'knowledge/domains');
const packs = {};
for (const f of fs.readdirSync(domainsDir).filter((f) => f.endsWith('.md')).sort()) {
  const raw = fs.readFileSync(path.join(domainsDir, f), 'utf8');
  const m = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) throw new Error(`${f}: missing front matter`);
  const meta = Object.fromEntries(m[1].split('\n').map((l) => { const i = l.indexOf(':'); return [l.slice(0, i).trim(), l.slice(i + 1).trim()]; }));
  packs[meta.id] = { label: meta.label, keywords: meta.keywords.split(',').map((k) => k.trim().toLowerCase()).filter(Boolean), text: m[2].trim() };
}

const out = `// GENERATED by scripts/gen-prompts.mjs — DO NOT EDIT. Edit the .md sources:
//   prompts/lens-v1.md · prompts/subject-fidelity-v1.md · prompts/library-v1.md
//   knowledge/domains/*.md
export const LENS = ${js(read('prompts/lens-v1.md'))};
export const SUBJECT_FIDELITY = ${js(read('prompts/subject-fidelity-v1.md'))};
export const READER_LIBRARY = ${js(read('prompts/library-v1.md'))};
export const DOMAIN_PACK_DATA = ${JSON.stringify(packs, null, 2)};
`;

if (process.argv.includes('--check')) {
  const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (cur !== out) { console.error('prompts/prompts.generated.js is stale — run node scripts/gen-prompts.mjs'); process.exit(1); }
  console.log('gen-prompts: up to date');
} else {
  fs.writeFileSync(OUT, out);
  console.log(`gen-prompts: wrote prompts/prompts.generated.js (${Object.keys(packs).length} domain packs)`);
}
